{
  "name": "autoseguro",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=22.18"
  },
  "scripts": {
    "chat": "node src/cli.ts",
    "test": "node --test --test-concurrency=1 test/*.test.ts",
    "typecheck": "tsc --noEmit",
    "lint": "oxlint src test",
    "check": "npm run typecheck && npm run lint && npm test"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "oxlint": "^1.0.0",
    "typescript": "^5.9.0"
  }
}

export const requiredFieldNames = [
  "plano",
  "idade",
  "veiculo_ano",
  "cep",
  "data_inicio",
] as const;

export type RequiredFieldName = (typeof requiredFieldNames)[number];
export type ConversationStage = "collecting" | "quoting" | "resolved" | "handoff";
export type Outcome = "resolved" | "awaiting_data" | "refused" | "handoff";
export type MessageType = "text" | "audio" | "image" | "document";

export interface FieldOrigin {
  message_id: string;
  source: "llm";
}

export interface CollectedValue<T> {
  value: T;
  origin: FieldOrigin;
}

export interface CollectedFields {
  plano?: CollectedValue<string>;
  idade?: CollectedValue<number>;
  veiculo_ano?: CollectedValue<number>;
  cep?: CollectedValue<string>;
  data_inicio?: CollectedValue<string>;
}

export interface QuotePayload {
  plano_id: string;
  idade: number;
  veiculo_ano: number;
  cep: string;
  data_inicio: string;
}

export interface ProRataPayment {
  dias_no_mes: number;
  dias_cobrados: number;
  valor_primeiro_pagamento: number;
}

export interface QuoteResponse {
  plano_id: string;
  plano_nome: string;
  premio_mensal: number;
  franquia: number;
  coberturas: string[];
  moeda: string;
  primeiro_pagamento_pro_rata?: ProRataPayment;
}

export interface AgentReply {
  text: string;
  outcome: Outcome;
  quote_request_id: string | null;
}

export interface ConversationState {
  version: 1;
  conversation_id: string;
  stage: ConversationStage;
  fields: CollectedFields;
  ambiguity_count: number;
  processed_messages: Record<string, AgentReply>;
  quote_request_id?: string;
  quote?: QuoteResponse;
  handoff_reason?: string;
}

export interface IncomingMessage {
  conversation_id: string;
  message_id: string;
  text: string;
  message_type: MessageType;
}

export interface CandidateFields {
  plano?: unknown;
  idade?: unknown;
  veiculo_ano?: unknown;
  cep?: unknown;
  data_inicio?: unknown;
}

export interface LanguageUnderstanding {
  fields: CandidateFields;
  intent: "continue" | "human" | "unsupported";
  ambiguous: boolean;
}

export interface UnderstandingInput {
  text: string;
  missing_fields: RequiredFieldName[];
  current_date: string;
}

export interface ReplyInput {
  draft: string;
  missing_fields: RequiredFieldName[];
}

export interface LanguageModel {
  understand(input: UnderstandingInput): Promise<LanguageUnderstanding>;
  phrase(input: ReplyInput): Promise<string>;
}

export interface QuoteAttempt {
  attempt: number;
  latency_ms: number;
  http_status: number | null;
  failure_kind: "timeout" | "network" | null;
}

export type QuoteResult =
  | { kind: "success"; quote: QuoteResponse; attempts: QuoteAttempt[] }
  | { kind: "refused"; reason: string; attempts: QuoteAttempt[] }
  | { kind: "handoff"; reason: string; attempts: QuoteAttempt[] };

export interface QuoteClientPort {
  request(
    payload: QuotePayload,
    quoteRequestId: string,
    onAttempt: (attempt: QuoteAttempt) => Promise<void>,
  ): Promise<QuoteResult>;
}

export interface AuditEvent {
  event: "message" | "quote_attempt" | "handoff";
  conversation_id: string;
  message_id: string;
  timestamp: string;
  stage: ConversationStage;
  collected_fields: Record<string, CollectedValue<unknown>>;
  quote_request_id: string | null;
  attempt: number | null;
  latency_ms: number | null;
  http_status: number | null;
  outcome: Outcome;
  handoff_reason: string | null;
  failure_kind: "timeout" | "network" | null;
}

const emailPattern = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/giu;
const cpfPattern = /(?<!\d)\d{3}[.\s]?\d{3}[.\s]?\d{3}[-\s]?\d{2}(?!\d)/gu;
const phonePattern = /(?<!\d)(?:\+?55[\s.-]*)?(?:\(\d{2}\)|\d{2})[\s.-]*9?\d{4}[\s.-]*\d{4}(?!\d)/gu;

export function redactSensitiveText(value: string): string {
  return value
    .replace(emailPattern, "<email_redacted>")
    .replace(cpfPattern, "<cpf_redacted>")
    .replace(phonePattern, "<phone_redacted>");
}

export function maskCep(value: string): string {
  const digits = value.replace(/\D/gu, "");
  return digits.length === 8 ? `${digits.slice(0, 2)}***-***` : "<cep_invalid>";
}

import { appendFile, mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { randomUUID } from "node:crypto";
import { maskCep, redactSensitiveText } from "./privacy.ts";
import type {
  AuditEvent,
  CollectedFields,
  CollectedValue,
  ConversationState,
} from "./types.ts";

const identifierPattern = /^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/u;
const stages = new Set(["collecting", "quoting", "resolved", "handoff"]);

function statePath(directory: string, conversationId: string): string {
  if (!identifierPattern.test(conversationId)) {
    throw new Error("conversation_id inválido");
  }
  return join(directory, `${conversationId}.json`);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseState(raw: string, conversationId: string): ConversationState {
  const value: unknown = JSON.parse(raw);
  if (
    !isRecord(value) ||
    value.version !== 1 ||
    value.conversation_id !== conversationId ||
    typeof value.stage !== "string" ||
    !stages.has(value.stage) ||
    !isRecord(value.fields) ||
    !isRecord(value.processed_messages) ||
    typeof value.ambiguity_count !== "number"
  ) {
    throw new Error(`Estado inválido para ${conversationId}`);
  }
  return value as unknown as ConversationState;
}

export class FileConversationStore {
  constructor(private readonly directory: string) {}

  async load(conversationId: string): Promise<ConversationState> {
    const path = statePath(this.directory, conversationId);
    try {
      return parseState(await readFile(path, "utf8"), conversationId);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
        throw error;
      }
      return {
        version: 1,
        conversation_id: conversationId,
        stage: "collecting",
        fields: {},
        ambiguity_count: 0,
        processed_messages: {},
      };
    }
  }

  async save(state: ConversationState): Promise<void> {
    const path = statePath(this.directory, state.conversation_id);
    await mkdir(this.directory, { recursive: true });
    const temporaryPath = `${path}.${randomUUID()}.tmp`;
    await writeFile(temporaryPath, `${JSON.stringify(state, null, 2)}\n`, {
      encoding: "utf8",
      mode: 0o600,
    });
    await rename(temporaryPath, path);
  }

  async reset(conversationId: string): Promise<void> {
    await rm(statePath(this.directory, conversationId), { force: true });
  }
}

export function fieldsForAudit(
  fields: CollectedFields,
): Record<string, CollectedValue<unknown>> {
  return Object.fromEntries(
    Object.entries(fields).map(([name, collected]) => [
      name,
      name === "cep"
        ? { ...collected, value: maskCep(String(collected.value)) }
        : collected,
    ]),
  );
}

export class AuditLog {
  constructor(private readonly path: string) {}

  async append(event: AuditEvent): Promise<void> {
    await mkdir(dirname(this.path), { recursive: true });
    const line = redactSensitiveText(JSON.stringify(event));
    await appendFile(this.path, `${line}\n`, { encoding: "utf8", mode: 0o600 });
  }
}

import type {
  CandidateFields,
  CollectedFields,
  QuotePayload,
  RequiredFieldName,
} from "./types.ts";
import { requiredFieldNames } from "./types.ts";

interface ValidatedValues {
  plano?: string;
  idade?: number;
  veiculo_ano?: number;
  cep?: string;
  data_inicio?: string;
}

export interface ValidationResult {
  values: ValidatedValues;
  errors: string[];
}

function normalizePlan(value: unknown): string | null {
  if (typeof value !== "string") {
    return null;
  }
  const plan = value.normalize("NFD").replace(/\p{Diacritic}/gu, "").trim().toLowerCase();
  return ["essencial", "completo", "premium"].includes(plan) ? plan : null;
}

function normalizeInteger(value: unknown, minimum: number, maximum: number): number | null {
  const parsed = typeof value === "number" ? value : Number(value);
  return Number.isInteger(parsed) && parsed >= minimum && parsed <= maximum ? parsed : null;
}

function normalizeCep(value: unknown): string | null {
  if (typeof value !== "string" && typeof value !== "number") {
    return null;
  }
  const digits = String(value).replace(/\D/gu, "");
  return digits.length === 8 ? `${digits.slice(0, 5)}-${digits.slice(5)}` : null;
}

function normalizeDate(value: unknown): string | null {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/u.test(value)) {
    return null;
  }
  const [year, month, day] = value.split("-").map(Number);
  if (year === undefined || month === undefined || day === undefined) {
    return null;
  }
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day
    ? value
    : null;
}

function assignIfPresent<T>(
  candidate: unknown,
  normalized: T | null,
  name: RequiredFieldName,
  label: string,
  values: ValidatedValues,
  errors: string[],
): void {
  if (candidate === undefined || candidate === null) {
    return;
  }
  if (normalized === null) {
    errors.push(`${label} inválido`);
    return;
  }
  Object.assign(values, { [name]: normalized });
}

export function validateCandidates(candidates: CandidateFields): ValidationResult {
  const values: ValidatedValues = {};
  const errors: string[] = [];
  assignIfPresent(candidates.plano, normalizePlan(candidates.plano), "plano", "plano", values, errors);
  assignIfPresent(candidates.idade, normalizeInteger(candidates.idade, 0, 200), "idade", "idade", values, errors);
  assignIfPresent(
    candidates.veiculo_ano,
    normalizeInteger(candidates.veiculo_ano, 1950, 2100),
    "veiculo_ano",
    "ano do veículo",
    values,
    errors,
  );
  assignIfPresent(candidates.cep, normalizeCep(candidates.cep), "cep", "CEP", values, errors);
  assignIfPresent(
    candidates.data_inicio,
    normalizeDate(candidates.data_inicio),
    "data_inicio",
    "data de início",
    values,
    errors,
  );
  return { values, errors };
}

export function mergeFields(
  fields: CollectedFields,
  values: ValidatedValues,
  messageId: string,
): CollectedFields {
  const merged = { ...fields };
  for (const [name, value] of Object.entries(values)) {
    Object.assign(merged, {
      [name]: { value, origin: { message_id: messageId, source: "llm" } },
    });
  }
  return merged;
}

export function missingFields(fields: CollectedFields): RequiredFieldName[] {
  return requiredFieldNames.filter((name) => fields[name] === undefined);
}

export function toQuotePayload(fields: CollectedFields): QuotePayload {
  if (!fields.plano || !fields.idade || !fields.veiculo_ano || !fields.cep || !fields.data_inicio) {
    throw new Error("Campos obrigatórios incompletos");
  }
  return {
    plano_id: fields.plano.value,
    idade: fields.idade.value,
    veiculo_ano: fields.veiculo_ano.value,
    cep: fields.cep.value,
    data_inicio: fields.data_inicio.value,
  };
}

import { readFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { createInterface } from "node:readline/promises";
import { stdin, stdout } from "node:process";
import { parseArgs } from "node:util";
import { AutoSeguroAgent } from "./agent.ts";
import { OpenAICompatibleLlm } from "./llm.ts";
import { AuditLog, FileConversationStore } from "./persistence.ts";
import { redactSensitiveText } from "./privacy.ts";
import { QuoteClient } from "./quote-client.ts";
import type { IncomingMessage, MessageType } from "./types.ts";

interface ReplayRecord {
  conversation_id?: unknown;
  message_id?: unknown;
  message_index?: unknown;
  sender_role?: unknown;
  message_type?: unknown;
  message_body?: unknown;
  text?: unknown;
}

const messageTypes = new Set<MessageType>(["text", "audio", "image", "document"]);

function readReplayRecord(line: string, fallbackConversationId: string, index: number): IncomingMessage | null {
  const record = JSON.parse(line) as ReplayRecord;
  if (record.sender_role !== undefined && record.sender_role !== "lead") {
    return null;
  }
  const conversationId = typeof record.conversation_id === "string"
    ? record.conversation_id
    : fallbackConversationId;
  const text = typeof record.text === "string" ? record.text : record.message_body;
  const rawType = typeof record.message_type === "string" ? record.message_type : "text";
  if (typeof text !== "string" || !messageTypes.has(rawType as MessageType)) {
    throw new Error(`Linha ${index + 1} do replay é inválida`);
  }
  const sourceIndex = typeof record.message_index === "number" ? record.message_index : index;
  const messageId = typeof record.message_id === "string"
    ? record.message_id
    : `${conversationId}-${sourceIndex}`;
  return {
    conversation_id: conversationId,
    message_id: messageId,
    message_type: rawType as MessageType,
    text,
  };
}

async function replay(path: string, conversationId: string, agent: AutoSeguroAgent): Promise<void> {
  const lines = (await readFile(path, "utf8")).split(/\r?\n/u).filter((line) => line.trim() !== "");
  for (const [index, line] of lines.entries()) {
    const message = readReplayRecord(line, conversationId, index);
    if (!message) {
      continue;
    }
    console.log(`Lead: ${redactSensitiveText(message.text)}`);
    const reply = await agent.handle(message);
    console.log(`AutoSeguro: ${reply.text}`);
  }
}

async function interactive(conversationId: string, agent: AutoSeguroAgent): Promise<void> {
  const terminal = createInterface({ input: stdin, output: stdout });
  console.log(`AutoSeguro: Olá. Envie "sair" para encerrar. Conversa ${conversationId}.`);
  let index = 0;
  try {
    while (true) {
      const text = await terminal.question("Você: ");
      if (text.trim().toLowerCase() === "sair") {
        return;
      }
      const reply = await agent.handle({
        conversation_id: conversationId,
        message_id: `${conversationId}-${index}`,
        message_type: "text",
        text,
      });
      console.log(`AutoSeguro: ${reply.text}`);
      index += 1;
    }
  } finally {
    terminal.close();
  }
}

async function main(): Promise<void> {
  const { values } = parseArgs({
    options: {
      conversation: { type: "string", short: "c" },
      replay: { type: "string", short: "r" },
      reset: { type: "boolean", default: false },
      help: { type: "boolean", short: "h", default: false },
    },
  });
  if (values.help) {
    console.log("npm run chat -- [--conversation ID] [--replay arquivo.jsonl] [--reset]");
    return;
  }
  const conversationId = values.conversation ?? `cli-${randomUUID()}`;
  const store = new FileConversationStore(process.env.STATE_DIR ?? ".runtime/conversations");
  if (values.reset) {
    await store.reset(conversationId);
  }
  const agent = new AutoSeguroAgent(
    store,
    new AuditLog(process.env.AUDIT_LOG_PATH ?? ".runtime/audit.jsonl"),
    OpenAICompatibleLlm.fromEnv(),
    new QuoteClient({
      baseUrl: process.env.QUOTE_API_URL ?? "http://127.0.0.1:8000",
      timeoutMs: Number(process.env.QUOTE_TIMEOUT_MS ?? "3000"),
      maxAttempts: Number(process.env.QUOTE_MAX_ATTEMPTS ?? "3"),
    }),
  );
  if (values.replay) {
    await replay(values.replay, conversationId, agent);
    return;
  }
  await interactive(conversationId, agent);
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`Erro: ${redactSensitiveText(message)}`);
  process.exitCode = 1;
});

