41:function parseProRata(value: unknown): ProRataPayment | null {
42:  if (!isRecord(value)) {
43:    return null;
44:  }
45:  if (
46:    !isFiniteNumber(value.dias_no_mes) ||
47:    !isFiniteNumber(value.dias_cobrados) ||
48:    !isFiniteNumber(value.valor_primeiro_pagamento)
49:  ) {
50:    return null;
51:  }
52:  return {
53:    dias_no_mes: value.dias_no_mes,
54:    dias_cobrados: value.dias_cobrados,
55:    valor_primeiro_pagamento: value.valor_primeiro_pagamento,
56:  };
