59:function parseQuote(value: unknown): QuoteResponse | null {
60:  if (!isRecord(value)) {
61:    return null;
62:  }
63:  if (
64:    typeof value.plano_id !== "string" ||
65:    typeof value.plano_nome !== "string" ||
66:    !isMoney(value.premio_mensal) ||
67:    !isMoney(value.franquia) ||
68:    !Array.isArray(value.coberturas) ||
69:    !value.coberturas.every((item) => typeof item === "string") ||
70:    value.moeda !== "BRL"
71:  ) {
72:    return null;
73:  }
74:  const quote: QuoteResponse = {
75:    plano_id: value.plano_id,
76:    plano_nome: value.plano_nome,
77:    premio_mensal: value.premio_mensal,
78:    franquia: value.franquia,
